"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  type FocusEvent,
  type HTMLAttributes,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from "react";
import { animate, motion, transform, useMotionValue, useMotionValueEvent, useReducedMotion, useTransform } from "framer-motion";
import { cn } from "@/lib/utils";
import { Deck } from "./Deck";
import { EYEBROW, EYEBROW_INDENT, HistoryList, SpotifyMark } from "./HistoryList";
import { DECK_OPEN_BRIGHTNESS, DECK_OPEN_SCALE, DECK_OPEN_X, DECK_OPEN_Y, LIVE_SPRING, OPEN_SPRING, PLAY_ANGLE, REST_ANGLE } from "./motion";
import { useReveal } from "./reveal";
import { formatAgo } from "./time";
import { splitTracks, type Track } from "./types";

// The last-played track over a machined turntable. Hover (or focus, or tap) and the header gives
// way to the plays before it, the deck slides aside and dims, the tonearm swings in and the record
// spins up.
//
// The whole hover is ONE motion value, `open`, sprung between 0 and 1. Every layer is a function of
// it (see useReveal), so there are no competing transitions: leaving halfway retraces the same path
// from wherever it is. The record's spin is separate physics (useRecordSpin) — it eases up to speed
// and coasts down, and its angle is never reset.

const DEFAULT_LABELS = { last: "Last played", now: "Now playing", before: "Before that", empty: "Nothing played yet" };

export interface TurntableCardProps extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** Plays, newest first. The first is on the deck; the next `history` show under "Before that". */
  tracks: Track[];
  /** Username in the footer, e.g. "sjk__music". Shown uppercase. */
  user?: string;
  /** How many earlier plays the hover reveals, 0–5. */
  history?: number;
  /** Override any of the card's words, for localisation. */
  labels?: Partial<typeof DEFAULT_LABELS>;
  /** Force the hover state open or closed. Leave undefined for normal hover/focus/tap behaviour. */
  open?: boolean;
}

export const TurntableCard = forwardRef<HTMLElement, TurntableCardProps>(function TurntableCard(
  {
    tracks,
    user,
    history = 3,
    labels,
    open: forced,
    className,
    style,
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onFocus,
    onBlur,
    onKeyDown,
    onClickCapture,
    ...rest
  },
  ref
) {
  const still = useReducedMotion() ?? false;
  const words = { ...DEFAULT_LABELS, ...labels };
  const { current, earlier } = splitTracks(tracks, history);
  const hasHistory = earlier.length > 0;
  const live = !!current?.nowPlaying;

  // ── Open state: mouse hover, keyboard focus, or a tap on touch screens. Escape dismisses. ──
  const root = useRef<HTMLElement | null>(null);
  const setRoot = useCallback(
    (node: HTMLElement | null) => {
      root.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref]
  );
  const [hover, setHover] = useState(false);
  const [focus, setFocus] = useState(false);
  const [tapped, setTapped] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const isOpen = forced ?? (!dismissed && (hover || focus || tapped));
  const lastPointer = useRef<string>("mouse");
  const title = useRef<HTMLAnchorElement | null>(null);
  const inHistory = (node: EventTarget | null) => node instanceof Element && !!node.closest("[data-tt-history]");

  useEffect(() => {
    if (!tapped) return;
    const close = (e: globalThis.PointerEvent) => {
      if (!root.current?.contains(e.target as Node)) setTapped(false);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [tapped]);

  // ── The one value everything follows. ──
  const open = useMotionValue(isOpen ? 1 : 0);
  useEffect(() => {
    const controls = animate(open, isOpen ? 1 : 0, still ? { duration: 0.15, ease: "linear" } : { type: "spring", ...OPEN_SPRING });
    return () => controls.stop();
  }, [isOpen, still, open]);

  const [interactive, setInteractive] = useState(isOpen);
  useMotionValueEvent(open, "change", (v) => setInteractive(v > 0.5));

  // With nothing earlier to show, the words stay put and only the deck responds.
  const closed = useMotionValue(0);
  const textOpen = hasHistory ? open : closed;

  const header = useReveal(textOpen, { range: [0, 0.45], out: true, y: -8, blur: 4, still });
  const footer = useReveal(textOpen, { range: [0, 0.35], out: true, y: 6, still });

  const deckX = useTransform(open, [0, 1], ["0%", still ? "0%" : DECK_OPEN_X]);
  const deckY = useTransform(open, [0, 1], ["0%", still ? "0%" : DECK_OPEN_Y]);
  const deckScale = useTransform(open, [0, 1], [1, still ? 1 : DECK_OPEN_SCALE]);
  const deckFilter = useTransform(open, (v) => {
    const b = still ? 1 : 1 - (1 - DECK_OPEN_BRIGHTNESS) * v;
    return b > 0.999 ? "none" : `brightness(${b.toFixed(3)})`;
  });
  // A song starting or stopping moves the arm on its own, slower spring, like lowering it by hand.
  // The arm follows whichever of hover and playback wants it further in.
  const playing = useMotionValue(live ? 1 : 0);
  useEffect(() => {
    const controls = animate(playing, live ? 1 : 0, still ? { duration: 0 } : { type: "spring", ...LIVE_SPRING });
    return () => controls.stop();
  }, [live, still, playing]);
  const armAngle = useTransform([open, playing], ([o, p]: number[]) => {
    const v = Math.max(transform(o, [0.05, 0.75], [0, 1]), p);
    return still ? (v > 0.5 ? PLAY_ANGLE : REST_ANGLE) : REST_ANGLE + (PLAY_ANGLE - REST_ANGLE) * v;
  });

  // ── Events, composed with any the caller passed. ──
  const handlers = {
    onPointerEnter(e: PointerEvent<HTMLElement>) {
      onPointerEnter?.(e);
      if (e.pointerType !== "mouse") return;
      setHover(true);
      setDismissed(false);
    },
    onPointerLeave(e: PointerEvent<HTMLElement>) {
      onPointerLeave?.(e);
      if (e.pointerType === "mouse") setHover(false);
    },
    onPointerDown(e: PointerEvent<HTMLElement>) {
      onPointerDown?.(e);
      lastPointer.current = e.pointerType;
    },
    onClickCapture(e: MouseEvent<HTMLElement>) {
      onClickCapture?.(e);
      // On touch, the first tap opens the card instead of following a link. Decided on click, not
      // pointerdown, so a swipe that starts on the card scrolls the page without opening it.
      // Keyboard-made clicks (detail 0) always go through.
      if (lastPointer.current === "mouse" || e.detail === 0 || forced !== undefined || isOpen) return;
      e.preventDefault();
      setTapped(true);
      setDismissed(false);
    },
    onFocus(e: FocusEvent<HTMLElement>) {
      onFocus?.(e);
      // The card opens when keyboard focus reaches the earlier plays, and closes again when it goes
      // back to the title, so focus never sits on something faded out. Mouse focus is ignored, so a
      // clicked link doesn't pin the card open after the pointer leaves.
      if (!(e.target as HTMLElement).matches?.(":focus-visible")) return;
      const toHistory = inHistory(e.target);
      setFocus(toHistory);
      if (toHistory) setDismissed(false);
    },
    onBlur(e: FocusEvent<HTMLElement>) {
      onBlur?.(e);
      if (!inHistory(e.relatedTarget)) setFocus(false);
    },
    onKeyDown(e: KeyboardEvent<HTMLElement>) {
      onKeyDown?.(e);
      if (e.key !== "Escape" || !isOpen) return;
      // The card is the layer Escape closes, so it stops here rather than also closing whatever hosts it.
      e.stopPropagation();
      // Keep the keyboard user's place: hand focus back to something that stays visible.
      if (inHistory(document.activeElement)) (title.current ?? root.current)?.focus();
      setDismissed(true);
      setTapped(false);
    },
  };

  const ago = formatAgo(current?.playedAt);
  const eyebrow = !current ? words.empty : live ? words.now : words.last;

  return (
    <article
      ref={setRoot}
      tabIndex={-1}
      aria-label={current ? `${eyebrow}: ${current.title} by ${current.artist}` : words.empty}
      className={cn(
        "relative isolate w-full max-w-[560px] select-none overflow-hidden rounded-[28px] text-left outline-none [container-type:inline-size]",
        className
      )}
      style={{
        aspectRatio: "560 / 360",
        background:
          "repeating-linear-gradient(135deg, rgba(255,255,255,0.013) 0 1px, transparent 1px 4px), linear-gradient(180deg, #181818, #121212)",
        boxShadow:
          "inset 0 0 0 1px rgba(255,255,255,0.06), inset 0 1px 0 rgba(255,255,255,0.07), 0 24px 48px -24px rgba(0,0,0,0.85)",
        ...style,
      }}
      {...rest}
      {...handlers}
    >
      {/* Deck: at rest it bleeds off the right and bottom edges; open, it shrinks into the corner. */}
      <motion.div
        className="absolute bottom-[-5cqw] right-[-9.29cqw] w-[67.86cqw] will-change-transform"
        style={{ x: deckX, y: deckY, scale: deckScale, filter: deckFilter, transformOrigin: "100% 100%" }}
      >
        <Deck image={current?.image} alt="" spinning={isOpen || live} armAngle={armAngle} reducedMotion={still} />
      </motion.div>

      {/* Scrim: keeps the list legible over the dimmed deck. */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          opacity: textOpen,
          background: "linear-gradient(90deg, #151515 0%, rgba(21,21,21,0.82) 45%, rgba(21,21,21,0) 75%)",
        }}
      />

      <div className="absolute inset-[clamp(18px,5cqw,28px)] z-10">
        {/* Stays put through the hover; both eyebrows leave room for it. Green while a song plays. */}
        <SpotifyMark live={live} />

        <motion.div style={{ ...header, pointerEvents: interactive && hasHistory ? "none" : "auto" }} className="pr-[2px]">
          <p className={cn(EYEBROW, EYEBROW_INDENT)}>{eyebrow}</p>
          {current &&
            (current.url ? (
              <a
                ref={title}
                href={current.url}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-[clamp(8px,2.2cqw,12px)] block truncate rounded-[4px] text-[clamp(17px,4.3cqw,24px)] font-semibold leading-[1.2] tracking-[-0.01em] text-[#e5e5e5] outline-none transition-colors duration-150 hover:text-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-white/35"
              >
                {current.title}
              </a>
            ) : (
              <p className="mt-[clamp(8px,2.2cqw,12px)] truncate text-[clamp(17px,4.3cqw,24px)] font-semibold leading-[1.2] tracking-[-0.01em] text-[#e5e5e5]">
                {current.title}
              </p>
            ))}
        </motion.div>

        {(user || ago) && (
          // The name gives way to the time when space runs out; the time never truncates.
          <motion.p
            style={footer}
            className="absolute bottom-0 left-0 flex max-w-[32cqw] whitespace-nowrap text-[clamp(9.5px,1.95cqw,11px)] font-semibold uppercase leading-none tracking-[0.12em] text-[#aaa]"
          >
            {user && <span className="min-w-0 truncate">{user}</span>}
            {user && ago && <span className="shrink-0 px-[0.45em]">·</span>}
            {ago && (
              <span className="shrink-0" suppressHydrationWarning>
                {ago}
              </span>
            )}
          </motion.p>
        )}

        {hasHistory && <HistoryList open={open} tracks={earlier} heading={words.before} interactive={interactive} still={still} />}
      </div>
    </article>
  );
});

export default TurntableCard;

"use client";

import { useState } from "react";
import { motion, type MotionValue } from "framer-motion";
import { formatAgo } from "./time";
import type { Track } from "./types";
import { useReveal } from "./reveal";

// The "Before that" list. Rows arrive one after another as `open` grows, each over its own
// overlapping slice of the range, so the stagger is positional rather than timed and runs in
// reverse when the card closes.

// Kept in a .tsx file on purpose: the docs Tailwind pass only scans .tsx for class names.
export const EYEBROW =
  "text-[clamp(11px,2.3cqw,13px)] font-medium uppercase leading-none tracking-[0.08em] text-[#888]";
/** Room on the left of each eyebrow for the Spotify mark. */
export const EYEBROW_INDENT = "pl-[calc(clamp(13px,2.7cqw,15px)+clamp(6px,1.45cqw,8px))]";

const SPOTIFY_PATH =
  "M12 0C5.4 0 0 5.4 0 12s5.4 12 12 12 12-5.4 12-12S18.66 0 12 0zm5.521 17.34c-.24.359-.66.48-1.021.24-2.82-1.74-6.36-2.101-10.561-1.141-.418.122-.779-.179-.899-.539-.12-.421.18-.78.54-.9 4.56-1.021 8.52-.6 11.64 1.32.42.18.479.659.301 1.02zm1.44-3.3c-.301.42-.841.6-1.262.3-3.239-1.98-8.159-2.58-11.939-1.38-.479.12-1.02-.12-1.14-.6-.12-.48.12-1.021.6-1.141C9.6 9.9 15 10.561 18.72 12.84c.361.181.54.78.241 1.2zm.12-3.36C15.24 8.4 8.82 8.16 5.16 9.301c-.6.179-1.2-.181-1.38-.721-.18-.601.18-1.2.72-1.381 4.26-1.26 11.28-1.02 15.721 1.621.539.3.719 1.02.419 1.56-.299.421-1.02.599-1.559.3z";

/** The Spotify mark at the card's top-left: muted grey at rest, Spotify green with a soft glow while a song plays. */
export function SpotifyMark({ live }: { live: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden
      className="absolute left-0 top-[-0.13em] z-10 size-[clamp(13px,2.7cqw,15px)] transition-[color,filter] duration-700 ease-out"
      style={{ color: live ? "#1DB954" : "#5f5f5f", filter: live ? "drop-shadow(0 0 5px rgba(29,185,84,0.55))" : "none" }}
    >
      <path fill="currentColor" d={SPOTIFY_PATH} />
    </svg>
  );
}

const ROW_START = 0.38;
const ROW_STEP = 0.08;
const ROW_SPAN = 0.4;

export function HistoryList({
  open,
  tracks,
  heading,
  interactive,
  still,
}: {
  open: MotionValue<number>;
  tracks: Track[];
  heading: string;
  /** False while mostly closed: rows can't be clicked. */
  interactive: boolean;
  still: boolean;
}) {
  const head = useReveal(open, { range: [0.3, 0.65], y: 8, still });

  return (
    // Rows stay in the tab order while closed: tabbing onto one is what opens the card for keyboard
    // users (see TurntableCard onFocus). Pointer clicks only land once it is mostly open.
    <div data-tt-history className="absolute inset-x-0 top-0 max-w-[49%]" style={{ pointerEvents: interactive ? "auto" : "none" }}>
      <motion.p style={head} className={`${EYEBROW} ${EYEBROW_INDENT}`}>
        {heading}
      </motion.p>
      <ol className="mt-[clamp(8px,2.2cqw,12px)] flex flex-col gap-[clamp(2px,0.7cqw,4px)]">
        {tracks.map((track, i) => (
          <HistoryRow key={`${i}-${track.title}`} track={track} open={open} index={i} still={still} />
        ))}
      </ol>
    </div>
  );
}

function HistoryRow({ track, open, index, still }: { track: Track; open: MotionValue<number>; index: number; still: boolean }) {
  const start = ROW_START + ROW_STEP * index;
  const style = useReveal(open, { range: [start, Math.min(1, start + ROW_SPAN)], y: 10, blur: 4, still });
  const ago = formatAgo(track.playedAt);
  const [failed, setFailed] = useState<string | null>(null);
  const showArt = track.image && failed !== track.image;

  const body = (
    <>
      <span className="relative size-[clamp(28px,6.4cqw,36px)] shrink-0 overflow-hidden rounded-[6px] bg-[#222] shadow-[0_0_0_1px_rgba(255,255,255,0.06),0_2px_6px_rgba(0,0,0,0.5)]">
        {showArt && (
          <img
            src={track.image}
            alt=""
            draggable={false}
            decoding="async"
            loading="lazy"
            onError={() => setFailed(track.image ?? null)}
            className="h-full w-full object-cover"
          />
        )}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[clamp(11.5px,2.4cqw,13.5px)] font-semibold leading-[1.3] text-[#e5e5e5]">{track.title}</span>
        <span className="flex whitespace-nowrap text-[clamp(10px,2.05cqw,11.5px)] leading-[1.35] text-[#888]">
          <span className="min-w-0 truncate">{track.artist}</span>
          {ago && (
            <span className="shrink-0 pl-[0.35em]" suppressHydrationWarning>
              · {ago}
            </span>
          )}
        </span>
      </span>
    </>
  );

  const row =
    "-mx-2 flex items-center gap-[clamp(9px,2.15cqw,12px)] rounded-[10px] px-2 py-[clamp(3px,0.9cqw,5px)] outline-none transition-colors duration-150 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-white/35";

  return (
    <motion.li style={style}>
      {track.url ? (
        <a href={track.url} target="_blank" rel="noopener noreferrer" className={`${row} hover:bg-white/[0.04]`}>
          {body}
        </a>
      ) : (
        <div className={row}>{body}</div>
      )}
    </motion.li>
  );
}

"use client";

import { useId } from "react";
import type { MotionValue } from "framer-motion";
import { cn } from "@/lib/utils";
import { Record } from "./Record";
import { Tonearm } from "./Tonearm";
import { useRecordSpin } from "./useRecordSpin";

// A machined turntable deck, drawn in a 380 × 290 coordinate space that scales as one piece.
// Back to front: the plinth (SVG), the platter well, the rotating platter + record, a fixed light
// layer over the record, then the tonearm. HTML layers are placed in that same space, in percent.

const W = 380;
const H = 290;
const PLATTER = { cx: 150, cy: 150, r: 128 };
const RECORD_R = 118;

const circleBox = (r: number) => ({
  left: `${((PLATTER.cx - r) / W) * 100}%`,
  top: `${((PLATTER.cy - r) / H) * 100}%`,
  width: `${((2 * r) / W) * 100}%`,
  height: `${((2 * r) / H) * 100}%`,
});

const LABEL_MASK = "radial-gradient(circle closest-side, transparent 42%, #000 45%)";

export interface DeckProps {
  /** Album art for the record label. */
  image?: string;
  alt: string;
  /** Whether the platter should turn; it eases up to speed and coasts to a stop. */
  spinning: boolean;
  /** Tonearm angle in degrees: 0 parked, ~21 on the lead-in grooves. */
  armAngle: MotionValue<number>;
  reducedMotion: boolean;
  className?: string;
}

export function Deck({ image, alt, spinning, armAngle, reducedMotion, className }: DeckProps) {
  const angle = useRecordSpin(spinning, { disabled: reducedMotion });
  const uid = useId();
  const id = (name: string) => `tt-${name}-${uid}`;
  const url = (name: string) => `url(#${id(name)})`;

  return (
    <div className={cn("relative select-none", className)} style={{ aspectRatio: `${W} / ${H}` }} aria-hidden>
      <svg viewBox={`0 0 ${W} ${H}`} className="absolute inset-0 h-full w-full overflow-visible">
        <defs>
          <linearGradient id={id("body")} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#202020" />
            <stop offset="100%" stopColor="#141414" />
          </linearGradient>
          <linearGradient id={id("bevel")} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="rgba(255,255,255,0.11)" />
            <stop offset="10%" stopColor="rgba(255,255,255,0.035)" />
            <stop offset="100%" stopColor="rgba(255,255,255,0.02)" />
          </linearGradient>
          <linearGradient id={id("knob")} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#3a3a3a" />
            <stop offset="100%" stopColor="#1c1c1c" />
          </linearGradient>
          <filter id={id("drop")} x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="12" />
          </filter>
        </defs>

        {/* plinth, its drop shadow and the lit top edge */}
        <rect x="6" y="14" width={W - 12} height={H - 6} rx="18" fill="#000" opacity="0.6" filter={url("drop")} />
        <rect x="0.5" y="0.5" width={W - 1} height={H - 1} rx="18" fill={url("body")} stroke={url("bevel")} />

        {/* debossed inner panel: a dark cut with a faintly lit lower lip */}
        <rect x="8.5" y="9.5" width={W - 17} height={H - 18} rx="12" fill="none" stroke="rgba(255,255,255,0.04)" />
        <rect x="8.5" y="8.5" width={W - 17} height={H - 18} rx="12" fill="none" stroke="rgba(0,0,0,0.6)" />

        {/* hinge slots */}
        {[114, 230].map((x) => (
          <g key={x}>
            <rect x={x} y="2" width="36" height="5" rx="2.5" fill="#0a0a0a" />
            <rect x={x + 1} y="6.5" width="34" height="0.8" rx="0.4" fill="rgba(255,255,255,0.06)" />
          </g>
        ))}

        {/* power LED: lit while the platter turns */}
        <circle cx="22" cy="24" r="3.2" fill="#070707" stroke="rgba(255,255,255,0.05)" />
        <circle
          cx="22"
          cy="24"
          r="1.7"
          fill="#fff"
          style={{
            opacity: spinning ? 0.95 : 0.12,
            filter: spinning ? "drop-shadow(0 0 2.5px rgba(255,255,255,0.85))" : "none",
            transition: "opacity 500ms ease, filter 500ms ease",
          }}
        />

        {/* start button and speed selector */}
        <circle cx="26" cy="266" r="10" fill="#0a0a0a" />
        <circle cx="26" cy="265.4" r="8" fill={url("knob")} stroke="rgba(255,255,255,0.08)" />
        <rect x="44" y="261" width="34" height="10" rx="5" fill="#0a0a0a" />
        <rect x="45.5" y="262" width="15" height="7.5" rx="3.75" fill={url("knob")} stroke="rgba(255,255,255,0.08)" />

        {/* pitch fader */}
        <rect x="355" y="150" width="7" height="112" rx="3.5" fill="#080808" stroke="rgba(255,255,255,0.04)" />
        <path d="M346 206 H350 M367 206 H371" stroke="rgba(255,255,255,0.18)" strokeWidth="1" />
        <rect x="349.5" y="198" width="18" height="10" rx="2.5" fill={url("knob")} stroke="rgba(255,255,255,0.1)" />
        <rect x="351" y="202.6" width="15" height="0.8" fill="rgba(255,255,255,0.35)" />
      </svg>

      {/* platter well */}
      <div
        className="absolute rounded-full bg-[#080808]"
        style={{ ...circleBox(PLATTER.r + 3), boxShadow: "inset 0 2px 4px rgba(0,0,0,0.9), 0 1px 0 rgba(255,255,255,0.04)" }}
      />

      <div className="absolute" style={circleBox(PLATTER.r)}>
        <Record image={image} alt={alt} angle={angle} />
      </div>

      {/* fixed light: two soft opposing speculars across the grooves, and the spindle */}
      <div
        className="pointer-events-none absolute rounded-full"
        style={{
          ...circleBox(RECORD_R),
          background:
            "conic-gradient(from 20deg, transparent 0 6%, rgba(255,255,255,0.09) 12%, transparent 20% 56%, rgba(255,255,255,0.055) 62%, transparent 70%)",
