import { useEffect, useLayoutEffect, useRef } from "react";
import { useMotionValue, type MotionValue } from "framer-motion";
import { RPM, stepSpin, type SpinState } from "./motion";

/**
 * The platter's rotation in degrees, as a motion value. While `active`, the record spins up to
 * `rpm`; when it goes false the record coasts down and stays at whatever angle it stopped on.
 * The frame loop runs only while the record is moving, and toggling `active` mid-spin never
 * restarts it or resets the angle; it only changes the speed the physics eases toward.
 * `disabled` (reduced motion) stops the record where it is.
 */
export function useRecordSpin(active: boolean, opts: { rpm?: number; disabled?: boolean } = {}): MotionValue<number> {
  const { rpm = RPM, disabled = false } = opts;
  const angle = useMotionValue(0);
  const state = useRef<SpinState>({ angle: 0, velocity: 0 });
  const live = useRef({ active, rpm });
  const frame = useRef<number | null>(null);

  // Read by the running loop, so a prop change steers it without restarting it.
  useLayoutEffect(() => {
    live.current = { active, rpm };
  }, [active, rpm]);

  useEffect(() => {
    const stop = () => {
      if (frame.current !== null) cancelAnimationFrame(frame.current);
      frame.current = null;
    };
    if (disabled) {
      stop();
      state.current.velocity = 0;
      return;
    }
    if (!active || frame.current !== null) return;

    let last = performance.now();
    const tick = (now: number) => {
      const next = stepSpin(state.current, (now - last) / 1000, live.current.active, live.current.rpm);
      last = now;
      state.current = next;
      angle.set(next.angle);
      frame.current = next.velocity === 0 && !live.current.active ? null : requestAnimationFrame(tick);
    };
    frame.current = requestAnimationFrame(tick);
  }, [active, disabled, angle]);

  useEffect(
    () => () => {
      if (frame.current !== null) cancelAnimationFrame(frame.current);
      frame.current = null;
    },
    []
  );

  return angle;
}

"use client";

import { useTransform, type MotionValue } from "framer-motion";

// One layer of the hover choreography. Every layer reads the same 0→1 `open` value through its own
// slice of that range, so the sequence is a pure function of one number: a half-finished hover
// reverses from exactly where it is, and closing plays the opening backwards.

export interface RevealOptions {
  /** Slice of `open` over which this layer moves. */
  range: [number, number];
  /** true: visible at open = 0 and leaving; false: arriving as `open` grows. */
  out?: boolean;
  /** Travel in px at the hidden end (negative = above). */
  y?: number;
  /** Blur in px at the hidden end. */
  blur?: number;
  /** Reduced motion: opacity only. */
  still?: boolean;
}

export function useReveal(open: MotionValue<number>, { range, out = false, y = 0, blur = 0, still = false }: RevealOptions) {
  const shown = useTransform(open, range, out ? [1, 0] : [0, 1]);
  const translate = useTransform(shown, (v) => (still ? 0 : (1 - v) * y));
  const filter = useTransform(shown, (v) => {
    const b = still ? 0 : (1 - v) * blur;
    return b > 0.05 ? `blur(${b.toFixed(2)}px)` : "none";
  });
  return { opacity: shown, y: translate, filter };
}

// Every tunable number for the card's motion lives here, so the feel is adjusted in one place.

/** Drives the whole hover: no overshoot, settles in about 450 ms, reverses from wherever it is. */
export const OPEN_SPRING = { stiffness: 170, damping: 26, mass: 1 };

/** The arm lowering onto the record when a song starts on its own: slower and heavier than hover. */
export const LIVE_SPRING = { stiffness: 60, damping: 16, mass: 1.2 };

/** Platter speed in revolutions per minute. */
export const RPM = 100 / 3;
/** Seconds for the platter to close ~63% of the gap to full speed: a quick, motor-driven start. */
export const SPIN_UP_TAU = 0.35;
/** Same for slowing down; longer, so the record coasts like a heavy platter. */
export const SPIN_DOWN_TAU = 0.7;
/** Below this speed (deg/s) a coasting record is treated as stopped. */
export const STOP_EPSILON = 0.5;

/**
 * Deck at full hover: shrinks into its bottom-right corner and lifts in from the edges so the whole
 * turntable sits inside the card, beside the list. At rest the 380 × 290 deck bleeds 52px off the
 * right and 28px off the bottom; moving it back by that bleed plus the card's 28px padding, written
 * as a share of the deck's own size, holds at every card width.
 */
export const DECK_OPEN_X = `${(-(52 + 28) / 380) * 100}%`;
export const DECK_OPEN_Y = `${(-(28 + 28) / 290) * 100}%`;
export const DECK_OPEN_SCALE = 0.64;
export const DECK_OPEN_BRIGHTNESS = 0.8;

/** Tonearm angles in degrees: parked on its rest, and playing on the lead-in grooves. */
export const REST_ANGLE = 0;
export const PLAY_ANGLE = 21;

export interface SpinState {
  /** Accumulated rotation in degrees. Never wrapped, so stopping never snaps. */
  angle: number;
  /** Degrees per second. */
  velocity: number;
}

/**
 * One frame of platter physics. Velocity eases exponentially toward the target speed (frame-rate
 * independent), then the angle integrates it. `dt` is clamped so a tab coming back from the
 * background doesn't leap the record forward.
 */
export function stepSpin(s: SpinState, dt: number, active: boolean, rpm: number = RPM): SpinState {
  const step = Math.min(Math.max(dt, 0), 0.05);
  const target = active ? rpm * 6 : 0;
  const tau = target > s.velocity ? SPIN_UP_TAU : SPIN_DOWN_TAU;
  let velocity = target + (s.velocity - target) * Math.exp(-step / tau);
  if (!active && Math.abs(velocity) < STOP_EPSILON) velocity = 0;
  return { angle: s.angle + velocity * step, velocity };
}

import type { Track } from "./types";

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/**
 * "just now", "12 min ago", "5 h ago", "3 d ago", then a short date ("23 Oct").
 * Returns null for anything it can't stand behind (missing, unparseable or in the future), so the
 * caller drops the time instead of printing "NaN" or "in -3 h".
 */
export function formatAgo(playedAt: Track["playedAt"], now: number = Date.now()): string | null {
  if (playedAt == null) return null;
  const t = playedAt instanceof Date ? playedAt.getTime() : typeof playedAt === "number" ? playedAt : Date.parse(playedAt);
  if (!Number.isFinite(t)) return null;
  const elapsed = now - t;
  if (elapsed < -MINUTE) return null; // clock skew up to a minute reads as "just now"
  if (elapsed < MINUTE) return "just now";
  if (elapsed < HOUR) return `${Math.floor(elapsed / MINUTE)} min ago`;
  if (elapsed < DAY) return `${Math.floor(elapsed / HOUR)} h ago`;
  if (elapsed < 7 * DAY) return `${Math.floor(elapsed / DAY)} d ago`;
  return new Date(t).toLocaleDateString("en-GB", { day: "numeric", month: "short" });
}

/** One play, newest first in any list. Shaped after Last.fm's `user.getrecenttracks`. */
export interface Track {
  title: string;
  artist: string;
  /** Album art URL; used for the record label and the history thumbnails. */
  image?: string;
  /** Where the title links to (Spotify, Last.fm…). */
  url?: string;
  /** When it was played: ISO string, epoch ms or Date. Unknown → null/undefined. */
  playedAt?: string | number | Date | null;
  /** True while the track is playing right now (Last.fm `@attr.nowplaying`). */
  nowPlaying?: boolean;
}

/** The card never shows more than this many earlier plays. */
export const MAX_HISTORY = 5;

/** Splits a newest-first list into the track on the deck and the earlier plays shown on hover. */
export function splitTracks(tracks: Track[], history: number): { current: Track | null; earlier: Track[] } {
  const count = Math.max(0, Math.min(MAX_HISTORY, Math.floor(history)));
  return { current: tracks[0] ?? null, earlier: tracks.slice(1, 1 + count) };
}

